#!/usr/bin/env python3
"""Appendix (app:traits): the trait-memory associations that survive FDR (analysis/trait_memory_v351.json: n_people, n_tests,
survivors_q05) and the embedding check (analysis/trait_memory.json part B: ridge from person-mean all-mpnet-base-v2 embeddings of
memory and reason, 10-fold CV r, permutation p over 200 shuffles; scripts/trait_memory.py).
-> paper_v2/sections/app_parts/app_traits.tex"""
import json, os
ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..")
A = json.load(open(os.path.join(ROOT, "analysis", "trait_memory_v351.json")))
B = json.load(open(os.path.join(ROOT, "analysis", "trait_memory.json")))
TN = {"HEXACO_HH_mean": "Honesty-Humility", "HEXACO_E_mean": "Emotionality", "HEXACO_EX_mean": "Extraversion", "HEXACO_A_mean": "Agreeableness",
      "HEXACO_C_mean": "Conscientiousness", "HEXACO_OP_mean": "Openness to Experience", "SIAS_mean": "Social anxiety (SIAS-6)",
      "Trust_Propensity_mean": "Trust: propensity", "Trust_Benevolence_mean": "Trust: benevolence", "Trust_Ability_mean": "Trust: ability",
      "Trust_Integrity_mean": "Trust: integrity", "PPTS_Affective_Responsiveness_mean": "PPTS: affective responsiveness",
      "PPTS_Cognitive_Responsiveness_mean": "PPTS: cognitive responsiveness", "PPTS_Interpersonal_Manipulation_mean": "PPTS: interpersonal manipulation",
      "PPTS_Egocentricity_mean": "PPTS: egocentricity"}
FN = {"rating_arousal": "Arousal rating of the remembered moment (mean)", "feelings__JOY": "Names joy (share of memories)",
      "shared_by__BOTH": "Both partners shared something personal (share)"}
def num(x): return ("$-$" if x < 0 else "+") + f"{abs(x):.2f}"[1:]
def q(x): return "$<$.001" if x < .001 else f"{x:.3f}"[1:]
rows = [f"{TN[s['trait']]} & {FN[s['feature']]} & {num(s['rho'])} & {q(s['q'])} & {s['n']} \\\\" for s in A["survivors_q05"]]
brow = [f"{TN[t]} & {num(v['r'])} & {v['p_perm']:.3f}"[:] + " \\\\" for t, v in B["B"].items()]
brow = [r.replace(" 0.", " .") for r in brow]
text = (f"We correlated each of the person's trait scores with how often each code appears in their memories, and with their mean ratings of the remembered moments and report lengths "
        f"(Spearman, {A['n_tests']} tests, {A['n_people']} people with at least three reports), and corrected with Benjamini--Hochberg \\citep{{benjamini1995controlling}}. "
        f"Table~\\ref{{tab:traits_all}} lists all {['zero','one','two','three','four','five','six','seven','eight','nine'][len(A['survivors_q05'])]} associations with $q<.05$. "
        "On every PPTS subscale a higher score means more psychopathic traits, so a higher cognitive-responsiveness score means less responsiveness. "
        "As a second check that does not depend on the codebook, we predicted each trait from the average sentence embedding (all-mpnet-base-v2) of a person's memories and reasons \\citep{reimers2019sentence} with cross-validated ridge regression "
        f"(Table~\\ref{{tab:traits_emb}}; {B['n_people']} people, permutation $p$ from 200 shuffles, uncorrected across 15 traits).\n")
t1 = ["\\begin{table}[t]", "\\centering\\footnotesize", "\\setlength{\\tabcolsep}{3pt}", "\\begin{tabular}{@{}p{0.27\\columnwidth}p{0.42\\columnwidth}rrr@{}}", "\\toprule",
      "Trait & Memory feature & $\\rho$ & $q$ & $n$ \\\\", "\\midrule"] + rows + ["\\bottomrule", "\\end{tabular}",
      f"\\caption{{Trait--memory associations surviving false-discovery correction ({A['n_tests']} tests).}}", "\\label{tab:traits_all}", "\\end{table}"]
t2 = ["\\begin{table}[t]", "\\centering\\footnotesize", "\\begin{tabular}{@{}lrr@{}}", "\\toprule", "Trait & CV $r$ & $p$ (perm.) \\\\", "\\midrule"] + brow + [
      "\\bottomrule", "\\end{tabular}", "\\caption{Predicting each trait from the embeddings of a person's memories (10-fold cross-validated ridge).}", "\\label{tab:traits_emb}", "\\end{table}"]
out = os.path.join(ROOT, "paper_v2", "sections", "app_parts"); os.makedirs(out, exist_ok=True)
open(os.path.join(out, "app_traits.tex"), "w").write("% Generated by scripts/tab_traits_appendix.py. Do not edit by hand.\n" + text + "\n" + "\n".join(t1) + "\n\n" + "\n".join(t2) + "\n")
print(len(rows), "survivors;", len(brow), "embedding rows")
